// 1. Determine execution trigger mode (Schedule vs Webhook)
const isWebhook = Boolean($input.item.json.body || $input.item.json.headers);
const inputBody = isWebhook ? ($input.item.json.body || $input.item.json) : {};

const region = (inputBody.region || 'US').toUpperCase();
const customVideos = inputBody.videos || [];

// 2. Return config context for downstream ingestion
return {
  json: {
    region,
    triggerSource: isWebhook ? 'webhook' : 'schedule',
    timestamp: new Date().toISOString(),
    hasCustomPayload: customVideos.length > 0,
    customVideos
  }
};

// Extract context from previous step
const context = $input.item.json;
const region = context.region || 'US';
let rawVideos = context.customVideos || [];

// If triggered by schedule without custom payload, generate curated sample trending dataset
if (rawVideos.length === 0) {
  rawVideos = [
    {
      videoId: 'dQw4w9WgXcQ',
      title: 'Rick Astley - Never Gonna Give You Up (Official Music Video)',
      channelName: 'Rick Astley',
      viewCount: '1540000000',
      durationSec: '213',
      category: 'Music',
      publishedAt: '2009-10-25T06:57:33Z'
    },
    {
      videoId: 'jNQXAC9IVRw',
      title: 'Me at the zoo',
      channelName: 'jawed',
      viewCount: '310000000',
      durationSec: '19',
      category: 'People & Blogs',
      publishedAt: '2005-04-24T03:31:52Z'
    }
  ];
}

// Normalize and clean each video record
const cleanedVideos = rawVideos.map((v, index) => {
  const videoId = v.videoId || v['Video ID'] || v.id;
  return {
    'Video ID': videoId,
    'Title': v.title || v['Title'] || 'Untitled Video',
    'Thumbnail': v.thumbnail || v['Thumbnail'] || (videoId ? `https://i.ytimg.com/vi/${videoId}/mqdefault.jpg` : ''),
    'Channel': v.channelName || v.channel || v['Channel'] || 'YouTube Creator',
    'Views': (v.viewCount ?? v.views ?? v['Views'] ?? '0').toString(),
    'Duration (sec)': (v.durationSec ?? v.duration ?? v['Duration (sec)'] ?? '0').toString(),
    'Published At': v.publishedTime || v.publishedAt || v['Published At'] || new Date().toISOString(),
    'Category': v.category || v['Category'] || 'Trending',
    'Country': region,
    'Trending Rank': index + 1
  };
}).filter(v => Boolean(v['Video ID']));

return {
  json: {
    region,
    count: cleanedVideos.length,
    videos: cleanedVideos,
    apiUrl: 'https://skipplay.app/api/sync/trending',
    syncSecret: 'skipplay_sync_secret_key_2026'
  }
};
